  'camPair.sonyIntro': 'Sony FX9/FX6/FX3/alpha-serie støtter Camera Remote API på port 8080 (default). Venice + andre pro-kameraer kan kreve egen Content Browser Mobile-protokoll og er ikke fullt støttet ennå.',
