  'camPair.connectSonyButton': 'Koble til Sony',
  'camPair.arriIntro': 'ARRI Web Remote støttes på Alexa Mini LF og Alexa 35 (firmware 7.x+). Web Remote må være aktivert i kameraets meny først (System → API).',
  'camPair.connectArriButton': 'Koble til ARRI',
  'camPair.zcamIntro': 'Z CAM-modeller (E2, E2-M4, F8, F6, ZF) eksponerer et åpent HTTP-API på port 80. Kameraet må være i Wi-Fi STA- eller AP-modus. Sjekk kamerameny → Network for IP-adresse.',
  'camPair.connectZcamButton': 'Koble til Z CAM',
  'camPair.blackmagicIntro': 'Blackmagic-kameraer (URSA Mini, Pocket Cinema, URSA Broadcast) styres via Bluetooth LE direkte fra nettleseren. Krever Chromium-browser (Chrome, Edge, Opera) og HTTPS — fungerer ikke i Safari eller på iOS.',
  'camPair.webBluetoothUnavailableBlackmagic': 'Web Bluetooth API er ikke tilgjengelig i denne nettleseren. Bruk Chrome/Edge på desktop, eller åpne LIVE SET PRO i iPad CaptureApp som har native Bluetooth-støtte.',
