  'camPair.goproIntro': 'GoPro HERO9, HERO10, HERO11, HERO12, HERO13, MAX og senere modeller med Open GoPro firmware støttes via Bluetooth LE. Aktiver Bluetooth-paring i kameramenyen → Connections → Connect Device → GoPro App → Pair Device.',
  'camPair.webBluetoothUnavailableGopro': 'Web Bluetooth API er ikke tilgjengelig. Bruk Chrome/Edge på desktop, eller åpne LIVE SET PRO i iPad CaptureApp (native Bluetooth).',
  'camPair.searchGoproButton': 'Søk etter GoPro',
  'camPair.goproHint': 'Open GoPro BLE-protokollen lar deg starte/stoppe opptak og endre FPS/WB/ISO. For media-overføring trengs Wi-Fi (kommer som oppfølgings-feature).',
  'camPair.ipadBridgeIntro': 'iPad CaptureApp kan bridge native-SDK-kameraer (RED Cinema RCP, DJI Mobile SDK, Panasonic Wi-Fi-modul, Bluetooth-protokoller via CoreBluetooth) til web-UI. iPad må kjøre LIVE SET PRO-bridge på samme nettverk, og kameraer paires fra iPad-appen først.',
