  'projCreate.worklog.culturalConsiderations': 'Kulturelle hensyn for {culture}',
  'projCreate.worklog.specialCulturalNote': 'Spesielle kulturelle hensyn må tas',
  'projCreate.cde.sikh.0': 'Chooda er en seremoni hvor bruden får røde armbånd og Haldi innebærer å smøre gurkemeie på brudeparet for renselse og velsignelser.',
  'projCreate.cde.sikh.1': 'En musikkfylt feiring med dans og sanger der familiene forbereder seg til bryllupet med glede og tradisjonelle opptredener.',
  'projCreate.cde.sikh.2': 'Anand Karaj er den hellige Sikh vielsesseremonien i Gurdwara, fulgt av resepsjon med mat og feiring.',
  'projCreate.cde.indisk.0': 'Ganesh Puja ber om velsignelser fra Ganeshas for å fjerne hindringer og Haldi påføres brudeparet for å rense og beskytte.',
  'projCreate.cde.indisk.1': 'Kunstferdig hennamaling påføres brudens hender og føtter i komplekse mønstre som symboliserer glede, åndelig oppvåkning og tilbud.',
  'projCreate.cde.indisk.2': 'En livlig feiring med tradisjonelle sanger, dans og musikk der begge familier deltar i opptredener og konkurranser.',
  'projCreate.cde.indisk.3': 'Den hellige Hindu vielsesseremonien med Saptapadi (syv skritt) og Mangalsutra, fulgt av festmiddag og tradisjonelle ritualer.',
  'projCreate.cde.pakistansk.0': 'Mehndi feiring hvor bruden får henna påført mens familie og venner synger tradisjonelle pakistanske bryllupssanger med tradisjonell musikk og dans.',
  'projCreate.cde.pakistansk.1': 'Baraat er brudgommens entre til bryllupet, og Nikkah er den religiøse islamske vielsesseremonien med signering av nikah-kontrakt.',
  'projCreate.cde.pakistansk.2': 'Walima er den tradisjonelle resepsjonen arrangert av brudgommens familie for å feire det nye ekteskapet med mat og glede.',
  'projCreate.cde.tyrkisk.0': 'En tradisjonsrik kveld hvor bruden får henna påført hendene mens kvinnelige gjester synger sorgtunge sanger om å forlate barndomshjemmet.',
  'projCreate.cde.tyrkisk.1': 'Den offisielle bryllupsdagen med sivil eller religiøs seremoni, fulgt av stor feiring med tradisjonell tyrkisk mat, musikk og dans.',
  'projCreate.cde.arabisk.0': 'Den islamske vielsesseremonien hvor nikah-kontrakten signeres i nærvær av vitner og familie, ofte fulgt av duaa og bønner.',
  'projCreate.cde.arabisk.1': 'Zaffe er en spektakulær prosesjon med musikk og dans som leder brudeparet til festen, fulgt av Walima resepsjon.',
  'projCreate.cde.somalisk.0': 'Den religiøse islamske vielsen med recitasjon av Koranen, nikah-kontrakt og duaa i nærvær av familie og samfunn.',
  'projCreate.cde.somalisk.1': 'Tradisjonell somalisk bryllupsfeiring med autentisk mat, kulturdans, poesi og musikk som feirer det nye ekteskapet.',
  'projCreate.cde.etiopisk.0': 'En tradisjonell etiopisk førbryllups-seremoni med velsignelser, bønner og familiesamling før den offisielle vielsen.',
  'projCreate.cde.etiopisk.1': 'Storslått feiring med tradisjonell etiopisk kaffe-seremoni, injera mat, kulturell musikk og dans som feirer den nye familien.',
  'projCreate.cde.nigeriansk.0': 'Vestlig-stil bryllup i kirke eller seremoni-lokale med hvit kjole og tradisjonelle europeiske bryllupstradisjoner.',
  'projCreate.cde.nigeriansk.1': 'Autentisk nigeriansk kulturell seremoni med tradisjonelle klær, ritualer, maten og musikk spesifikk for familiens stamme eller region.',
  'projCreate.cde.muslimsk.0': 'En intim feiring hvor bruden og kvinnelige gjester får henna påført i vakre mønstre mens de synger tradisjonelle sanger.',
  'projCreate.cde.muslimsk.1': 'Nikkah er den offisielle islamske vielsesseremonien med kontraktsignering, fulgt av Walima resepsjon for å feire ekteskapet.',
  'projCreate.cde.libanesisk.0': 'En livlig feiring hvor bruden får henna påført av eldre kvinnelige slektninger mens gjester deltar i tradisjonell libanesisk musikk.',
  'projCreate.cde.libanesisk.1': 'Spektakulær Zaffe innmarsj med trommer og ululating, fulgt av resepsjon med autentisk libanesisk mat og tradisjonell dabke dans.',
  'projCreate.cwt.sikh.0.tasks.0': 'Møte med familiene for å diskutere tidsplan',
