  'prodMedia.j008': 'Fullfør briefen',
  'prodMedia.j009': 'Mobilutkast lagres automatisk',
  'prodMedia.j010': 'Ett skjermkort med det viktigste produsenten trenger for å forstå retning, leveranse og oppfølging.',
  'prodMedia.j011': 'Briefen er låst fordi prosjektet er godkjent. Endringer i mål, budskap, referanser og kontaktpunkt må tas gjennom en ny godkjenningsrunde.',
  'prodMedia.j012': 'Samme struktur som produsenten bruker videre i planlegging og levering. Klienten beskriver målet, kroken og handlingen direkte her.',
  'prodMedia.j013': 'Last opp referanser direkte i briefen',
  'prodMedia.j014': 'Legg ved filmer, PDF-er, bilder eller annet grunnlag her. Referansen blir lagret i prosjektet og kan brukes videre i prosjektrommet.',
