  'prodMedia.j020': 'Her konkretiseres hva som beviser budskapet og hvordan innholdet skal fordeles på flater.',
  'prodMedia.j021': 'Storyboard og inspirasjoner',
  'prodMedia.j022': 'Klienten ser scener og frames i rolig form, og kan legge inn inspirasjoner og referanser direkte på riktig scene uten å rote til produksjonseditoren.',
  'prodMedia.j023': 'Klienten får oversikt over hvilke scener som faktisk er blokkert i storyboardet og kan peke inspirasjoner inn på rett sted.',
