  'prodMedia.j031': 'Ingen storyboard-inspirasjoner er registrert ennå.',
  'prodMedia.j032': 'Manus og endringsforslag',
  'prodMedia.j033': 'Klienten leser manus i oversiktlig form og skriver forslag til endringer som egne innspill. Originalteksten blir ikke overskrevet direkte i klientflaten.',
  'prodMedia.j034': 'Ingen scener er koblet til manusgrunnlaget ennå.',
  'prodMedia.j035': 'Foreslå endring',
  'prodMedia.j036': 'Bruk dette til omskrivninger, tydeliggjøringer eller forslag til scenen, ikke til å redigere selve manuset direkte.',
  'prodMedia.j037': 'Endringsforslagene ligger som egne punkter teamet kan følge opp, uten å blande klientkommentarer inn i selve manusstrukturen.',
  'prodMedia.j038': 'Ingen manusforslag er registrert ennå.',
  'prodMedia.j039': 'Shotlist overview',
  'prodMedia.j040': 'Dette er klientvisningen av shotlisten: tydelig, rolig og sceneorientert. Den viser hva som skal dekkes, hvor og med hvem, men ikke den interne produksjonsstøyen.',
  'prodMedia.j041': 'Oversikten er bevisst komprimert til plan, scene, sted, cast og beskrivelse. Det gjør den rask å lese i møter og trygg å sende til klient uten at de må tolke intern shot-detaljering.',
  'prodMedia.j042': 'Scene / klipp',
