  'prodMedia.j052': 'Forslagene fyller ut merkevareguiden, men klienten kan fortsatt justere alt manuelt etterpå.',
  'prodMedia.j053': 'Dra logoen i previewen for å snappe den til nærmeste plassering. Valget under oppdateres automatisk.',
  'prodMedia.j054': 'Velg leveransen du faktisk skal vurdere. Previewen oppdaterer safe zone, margin og logo-oppførsel mot riktig format for klientvisningen.',
  'prodMedia.j055': 'Logovariant for denne leveransen',
  'prodMedia.j056': 'Dra logoen i rammen for å velge plassering. Previewen bruker nå aktiv logovariant og riktig safe zone for valgt leveranse.',
