  'prodMedia.j058': 'Legg til farge',
  'prodMedia.j059': 'Definer språk og regler',
  'prodMedia.j060': 'Fyll inn hvordan merkevaren skal høres ut, se ut og holdes konsekvent.',
  'prodMedia.j061': 'Lagre når uttrykket faktisk kan brukes av produksjonsteamet.',
  'prodMedia.j062': 'Hold all klienttilgang i ett kontrollert spor. Passord krypteres med AES-256-GCM, krever 2FA-bekreftelse hver gang de skal vises, og alle reveal-events logges i audit-historikken. Start med delegert tilgang og invite-flyt — hvis kunden faktisk må dele noe sensitivt, blir det aldri lagret som klartekst.',
